            "why": "地球一直绕着一根看不见的轴自转，这根轴穿过北极和南极。在两极正中间、离地轴最远的那一圈，就是赤道。它把地球正好分成北半球和南半球。只要知道南北极在哪，谁都能找到同一条赤道，不用开会商量。",
