            "idea": "**纬度**回答\"这个地方在赤道以北（或以南）多远\"，用角度来量，不用公里。",
            "why": "地球是圆的。从地心看出去，从赤道往北走得越远，看过去的方向就转得越多，所以\"走多远\"可以换成\"转了多大的角\"。用角度的好处是：数字和地球大小无关，0° 就是赤道，最大的那个数就是极点。把纬度相同的地方连起来，是一圈和赤道平行的圆，叫纬线。",
            "takeaway": "纬度 = 从赤道往北或往南转过的角度，范围 0°～90°。",
