            "why": "这些变化由自主神经系统（主要是交感神经）发动，作用是让身体快速进入\"准备应战\"的状态：心跳快了，肌肉能拿到更多血液。\"自主\"的意思是它自己运转，你没法直接命令心跳慢下来。研究者用仪器测它，比如心率、皮肤出汗的程度。",
