            "why": "如果情绪就是\"察觉到身体变化\"，那每种情绪都得有一套自己独特的身体反应，否则大脑分不出来。可实际测量时，很多情绪的心跳、出汗、呼吸变化大同小异。后来有研究找到过一些小差别，但远不够把每种情绪分清。",
            "takeaway": "最大的漏洞：不同情绪的身体反应很相似，难以靠它区分情绪。",
            "example": "抢到演唱会门票的那一秒，和被人当面冒犯的那一秒，你都会心跳加速、脸发热。身体信号差不多，你却清楚知道一个是狂喜，一个是生气。区分它们的，似乎不只是身体。",
