            "title": "西边为什么这么高：板块相撞",
            "idea": "地球表面不是完整的一块，而像裂开的蛋壳，分成几大块，叫**板块**。板块在极慢地移动，两块撞到一起，交界处的地面就被挤高。",
            "why": "板块下面是又热又软、能极慢流动的岩石，板块\"浮\"在上面，一年只挪几厘米。两块迎面相撞，谁也推不动谁，交界处的岩层无处可去，只能往上拱、往上叠，慢慢变成高山和高原。",
            "takeaway": "板块相撞、互相挤压，把交界处推高；青藏高原就是这样被挤出来的。",
            "example": "大约 5000 万年前，载着印度的印度板块（课本里把它归在印度洋板块）一路向北，撞上了中国所在的亚欧板块。交界处被挤出了喜马拉雅山和青藏高原，直到今天，高原还在缓慢抬升。",
