            "title": "二因素：唤醒 + 标签",
            "idea": "1962 年沙赫特和辛格提出**二因素理论**：情绪 = 生理唤醒 + 认知标签。身体给强度，大脑给名字。",
            "why": "身体只能告诉你\"我很激动\"，说不出为什么激动。大脑会马上找原因：看看周围发生了什么，再给这份激动贴上标签，是害怕、生气还是兴奋。唤醒决定情绪有多强，标签决定它是哪一种，缺一样都不成情绪。",
            "takeaway": "二因素理论：情绪 = 生理唤醒 + 认知标签。",
            "example": "唤醒像音量，标签像调式。同样开到很大的音量，大调听起来欢腾，小调听起来悲壮。光有音量，你不知道这是首什么歌。",
