            "title": "局限：方法可能\"帮了忙\"",
            "idea": "埃克曼的结论影响很大，但也有学者质疑：认出表情的比例，可能被研究方法抬高了。",
            "why": "在\"几张照片里挑一张\"的做法里，即使不太确定，也能靠排除法选对。后来有研究改成不给选项，请人自己说出\"这张脸是什么情绪\"，不同文化之间的一致程度就明显降低。也有学者认为，情绪怎么分类，很大程度上受文化和语言影响。",
            "takeaway": "基本表情有跨文化共通性，但程度可能没那么高。",
            "example": "像选择题和填空题的区别：给你几个选项，你可能蒙对；让你自己写答案，就难多了。所以今天较稳妥的说法是：基本表情有跨文化的共同基础，但没有早年想的那样整齐划一。",
