            "why": "今天要问：这脚\"油门\"踩多深最好？踩得越深，表现就越好吗？",
            "takeaway": "生理唤醒有高有低，今天看它和表现的关系。",
            "example": "上台前心怦怦跳，是唤醒高；下午犯困、提不起劲，是唤醒低。",
            "review": true,
