            "why": "原始实验用的是小鼠和电击强度，后来人们才把它推广成\"唤醒和表现\"的关系。\"唤醒\"本身很笼统，心跳快和脑子兴奋不完全是一回事；每个人的最佳点也不同。还有研究发现，简单任务上唤醒很高时，表现也不一定明显下降。",
