            "why": "中文的元音没有长短之分，所以很多人把两个读成一样。可英语里长短不同就是不同的词：[[cheap]] 是便宜，[[chip]] 是薯片；[[sheep]] 是绵羊，[[ship]] 是船。短音不只是短，嘴也更松，舌头稍低一点。",
