            "idea": "上一张说到，今天比较两种调节：换解释，和压表现。心理学家格罗斯提出**情绪调节的过程模型**：情绪按\"情境 → 注意 → 评价 → 反应\"一步步产生。",
            "why": "情绪不是一下子炸开的，而是一环接一环：先遇到一个情境，注意到其中某个细节，对它做出评价，最后才有身体和表情上的反应。每一环都可以介入：越早介入，后面的环节还没启动，越省力；越晚介入，情绪已经起来了，越费劲。",
            "takeaway": "情绪按情境、注意、评价、反应产生，越早介入越省力。",
