            "why": "评价在反应之前，所以换掉评价，反应还没完全起来就被改了方向：主观体验、生理唤醒、外部表现都会跟着变小。它改的不是事情，而是事情对你的意义，和拉扎勒斯的\"评价\"、二因素的\"标签\"在同一个位置。",
