            "idea": "上一张说到，互补色等量又高纯度，就会冲。黑、白、灰叫**中性色**。它们几乎没有色相，纯度接近零。",
            "why": "第 1 天学过，色相由反射得最多的那种光决定。黑、白、灰对各种颜色的光一视同仁：白几乎全反射，黑几乎全吸收，灰各反射一部分。没有哪种光特别多，就没有色相。颜色打架靠的是色相对立，没有色相，就不参与打架，所以几乎能配一切。",
            "takeaway": "中性色几乎没有色相，不参与色相冲突，所以百搭。",
            "example": "白 T 恤配什么颜色的裤子都不容易出错，黑色小包几乎能配任何一套。它们不和别人抢色相，只负责提亮或压暗。",
