            "idea": "上一张说到，近中性色色相很弱，能当中性色用，又更温和。在两个冲突的颜色之间放一块中性色，冲突就被隔开了，这叫**缓冲**。强色旁边有了安静的地方，反而更亮眼。",
            "why": "冲突来自两个对立的颜色直接挨着、互相顶。中间隔一块不带色相的颜色，它们就不再直接碰面；中性色面积一大，红和绿又缩成了小面积点缀（第 11 天）。强色周围安静了，视线就集中到它身上。",
