            "title": "不合理信念的三个特征",
            "idea": "上一张说到，拍得到的是诱发事件，下判断的是信念。让人陷进去出不来的，往往是**不合理信念**。它有三个常见特征，可以像查错别字一样把它找出来。",
            "why": "埃利斯发现，造成强烈、持久痛苦的信念，常常带着三种\"夸张\"：绝对化要求，\"必须\"\"一定\"\"应该\"；过分概括化，一次失败就全盘否定自己或别人；糟糕至极，\"完了，一切都毁了\"。它们把一件具体的事放大成了全部。",
            "takeaway": "不合理信念三特征：绝对化要求、过分概括化、糟糕至极。",
            "example": "一条视频数据很差。\"我每条都必须爆\"是绝对化要求；\"我就是没天赋\"是过分概括化；\"这个号彻底完了\"是糟糕至极。合理的说法是：\"我希望每条都爆，但做不到也能接受。\"",
