            "why": "信念不是事实，可以被检验。辩论就是像律师一样追问它：证据在哪？有没有别的解释？就算是真的，真有那么糟吗？信念被问得站不住，情绪后果也就松动了。这和上一关的认知重评是同一个思路，只是步骤更具体。",
