            "title": "发音 · 英语按重音打拍子",
            "idea": "上一张记下了这几个词。英语说话有拍子：重读的词落在拍子上，中间的小词又轻又快地挤过去，像音乐里的强拍和弱拍。",
            "why": "中文差不多一个字一拍，字越多说得越久。英语按**重音**算时间：两个重音之间的时间差不多，中间小词再多，也得挤进去，所以 a、the、was、and 会变轻变快。一个字一个字平均地念，节奏就不像英语，也会听不出那些被挤扁的小词。",
            "takeaway": "英语按重音打拍子，小词挤在拍子之间。",
