            "idea": "上一张说到，英语按重音打拍子，小词挤在拍子之间。这两周学了四种说时间的办法。选哪个，只问一句：这件事在时间线的哪里？",
            "why": "英语把时间做在动词上（第 8 天）。中文有\"上周\"\"现在\"\"下周\"就够了，英语有了这些词，动词还是要跟着变。所以说每个动词之前，都先想一下它在时间线的哪里。",
